import { useState } from 'react';

import { Badge } from '../badge';

import { cn } from '../../../utils/ui/cn';

import type { TabItem, TabsProps, TabSize, TabVariant } from '../../../types/ui/tabs.types';

const sizeStyles: Record<TabSize, { button: string; icon: string; text: string }> = {
  sm: {
    button: 'px-2.5 py-1 text-xs gap-1.5',
    icon: 'w-3.5 h-3.5',
    text: 'text-xs',
  },
  md: {
    button: 'px-3 py-1.5 text-sm gap-2',
    icon: 'w-4 h-4',
    text: 'text-sm',
  },
  lg: {
    button: 'px-4 py-2 text-base gap-2.5',
    icon: 'w-4.5 h-4.5',
    text: 'text-base',
  },
};

const getVariantListStyles = (variant: TabVariant, isDark: boolean): string => {
  if (isDark) {
    switch (variant) {
      case 'underline':
        return 'border-b border-slate-800 gap-4 bg-transparent p-0';
      case 'bordered':
        return 'border border-slate-700/80 p-0.5 rounded-lg bg-slate-900 gap-1';
      case 'pills':
      case 'default':
      default:
        return 'bg-slate-800/80 border border-slate-700/60 p-0.5 rounded-lg gap-1';
    }
  }

  switch (variant) {
    case 'pills':
      return 'bg-slate-100/90 p-1 rounded-xl gap-1';
    case 'default':
      return 'bg-slate-200/70 p-1 rounded-xl gap-1';
    case 'underline':
      return 'border-b border-slate-200 gap-4 bg-transparent p-0';
    case 'bordered':
      return 'border border-slate-200 p-1 rounded-xl bg-white gap-1';
    default:
      return 'bg-slate-100/90 p-1 rounded-xl gap-1';
  }
};

export function Tabs({
  items = [],
  value,
  defaultValue,
  onChange,
  variant = 'default',
  size = 'md',
  theme = 'light',
  className = '',
  tabListClassName = '',
  contentClassName = '',
  fullWidth = false,
  extra,
  children,
}: TabsProps) {
  const isDark = theme === 'dark';
  const initialTab = defaultValue || items[0]?.id || '';
  const [internalValue, setInternalValue] = useState(initialTab);

  const activeTabId = value !== undefined ? value : internalValue;

  const handleTabClick = (tab: TabItem) => {
    if (tab.disabled) return;
    if (value === undefined) {
      setInternalValue(tab.id);
    }
    onChange?.(tab.id);
  };

  const activeItem = items.find((item) => item.id === activeTabId);

  const getButtonStyles = (tab: TabItem, isActive: boolean) => {
    const sizeConfig = sizeStyles[size];
    const base = cn(
      'inline-flex items-center justify-center font-medium transition-all select-none',
      sizeConfig.button,
      fullWidth ? 'flex-1' : '',
      tab.disabled ? 'opacity-40 cursor-not-allowed' : 'cursor-pointer'
    );

    if (isDark) {
      switch (variant) {
        case 'underline':
          return cn(
            base,
            'rounded-none border-b-2 -mb-px pb-2',
            isActive
              ? 'border-emerald-400 text-white font-semibold'
              : 'border-transparent text-slate-400 hover:text-white hover:border-slate-700'
          );
        case 'pills':
        case 'default':
        case 'bordered':
        default:
          return cn(
            base,
            'rounded-md',
            isActive
              ? 'bg-slate-700 text-white shadow-2xs font-semibold'
              : 'text-slate-400 hover:text-white hover:bg-slate-800/50'
          );
      }
    }

    switch (variant) {
      case 'underline':
        return cn(
          base,
          'rounded-none border-b-2 -mb-px pb-2',
          isActive
            ? 'border-emerald-600 text-emerald-800 font-semibold'
            : 'border-transparent text-slate-500 hover:text-slate-800 hover:border-slate-300'
        );
      case 'pills':
      case 'default':
      case 'bordered':
      default:
        return cn(
          base,
          'rounded-lg',
          isActive
            ? 'bg-white text-slate-900 shadow-2xs font-semibold'
            : 'text-slate-600 hover:text-slate-900 hover:bg-slate-200/50'
        );
    }
  };

  return (
    <div className={cn('w-full flex flex-col', className)}>
      <div className="flex flex-wrap items-center justify-between gap-2.5">
        <div
          role="tablist"
          className={cn(
            'inline-flex flex-wrap items-center',
            getVariantListStyles(variant, isDark),
            fullWidth ? 'w-full' : '',
            tabListClassName
          )}
        >
          {items.map((tab) => {
            const isActive = tab.id === activeTabId;
            return (
              <button
                key={tab.id}
                role="tab"
                type="button"
                aria-selected={isActive}
                disabled={tab.disabled}
                onClick={() => handleTabClick(tab)}
                className={getButtonStyles(tab, isActive)}
              >
                {tab.icon && <span className="shrink-0">{tab.icon}</span>}
                <span>{tab.label}</span>
                {tab.badge !== undefined && (
                  <Badge
                    variant={tab.badgeVariant || (isActive ? 'success' : 'default')}
                    size="xs"
                    className="ml-1"
                  >
                    {tab.badge}
                  </Badge>
                )}
              </button>
            );
          })}
        </div>

        {extra && <div className="shrink-0">{extra}</div>}
      </div>

      {(activeItem?.content || children) && (
        <div role="tabpanel" className={cn('mt-3 w-full', contentClassName)}>
          {activeItem?.content || children}
        </div>
      )}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  TabItem,
  TabsProps,
  TabSize,
  TabVariant,
} from '../../../types/ui/tabs.types';
