import { cn } from '../../../utils/ui/cn';

import type {
  ContainerContentProps,
  ContainerGap,
  ContainerPadding,
} from '../../../types/ui/container.types';

const paddingClasses: Record<ContainerPadding, string> = {
  none: 'p-0',
  small: 'p-4',
  medium: 'p-6',
  large: 'p-8',
};

const gapClasses: Record<ContainerGap, string> = {
  none: '',
  small: 'gap-3',
  medium: 'gap-5',
  large: 'gap-8',
};

export function ContainerContent({
  className = '',
  padding = 'none',
  gap = 'none',
  children,
  ...props
}: ContainerContentProps) {
  return (
    <div
      className={cn(
        'w-full flex-1 min-h-0',
        paddingClasses[padding],
        gap !== 'none' && 'flex flex-col',
        gapClasses[gap],
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { ContainerContentProps } from '../../../types/ui/container.types';
