import { useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { AlertCircle } from 'lucide-react';

import { CodeGutter } from './CodeGutter';
import { FullScreenHeader } from './FullScreenHeader';
import { FullScreenStatusBar } from './FullScreenStatusBar';
import { FullScreenToolbar } from './FullScreenToolbar';
import { JsonTreeViewer } from './JsonTreeViewer';
import { SplitterHandle } from './SplitterHandle';

import { cn } from '../../../utils/ui/cn';

import type {
  KeyboardEvent,
  MouseEvent as ReactMouseEvent,
  TouchEvent as ReactTouchEvent,
  UIEvent,
} from 'react';
import type {
  CodeEditorTheme,
  CodeEditorViewMode,
  FullScreenCodeEditorProps,
} from '../../../types/ui/code-editor.types';

export function FullScreenCodeEditor({
  isOpen,
  onClose,
  value,
  onSave,
  language = 'json',
  theme: initialTheme = 'dark',
  title = 'Code Editor',
  subtitle,
  badge,
  readOnly = false,
  initialViewMode = 'split',
  initialSplitRatio = 50,
  className = '',
}: FullScreenCodeEditorProps) {
  const [currentValue, setCurrentValue] = useState(value);
  const [theme, setTheme] = useState<CodeEditorTheme>(initialTheme);
  const [viewMode, setViewMode] = useState<CodeEditorViewMode>(initialViewMode);
  const [splitRatio, setSplitRatio] = useState<number>(initialSplitRatio);
  const [isDraggingSplit, setIsDraggingSplit] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [copied, setCopied] = useState(false);

  // Undo / Redo history
  const [history, setHistory] = useState<string[]>([value]);
  const [historyIndex, setHistoryIndex] = useState(0);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const gutterRef = useRef<HTMLDivElement>(null);
  const splitContainerRef = useRef<HTMLDivElement>(null);

  // Sync internal state when opened or value prop changes
  useEffect(() => {
    if (isOpen) {
      setCurrentValue(value);
      setHistory([value]);
      setHistoryIndex(0);
      setTheme(initialTheme);
      setSplitRatio(initialSplitRatio);
    }
  }, [isOpen, value, initialTheme, initialSplitRatio]);

  // Handle escape to close & overflow lock
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: globalThis.KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = originalOverflow;
    };
  }, [isOpen, onClose]);

  // Update content with undo/redo history
  const updateContentWithHistory = (newVal: string) => {
    setCurrentValue(newVal);
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newVal);
    if (newHistory.length > 50) newHistory.shift();
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      const prev = history[historyIndex - 1];
      setHistoryIndex(historyIndex - 1);
      setCurrentValue(prev);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const next = history[historyIndex + 1];
      setHistoryIndex(historyIndex + 1);
      setCurrentValue(next);
    }
  };

  // Keyboard shortcuts
  const handleEditorKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
      e.preventDefault();
      onSave?.(currentValue);
      return;
    }
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') {
      if (e.shiftKey) {
        e.preventDefault();
        handleRedo();
      } else {
        e.preventDefault();
        handleUndo();
      }
    } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'y') {
      e.preventDefault();
      handleRedo();
    }
  };

  // Parse JSON and check validity
  const { parsedJson, isValidJson, parseError } = useMemo(() => {
    if (language !== 'json') {
      return { parsedJson: null, isValidJson: true, parseError: null };
    }
    if (!currentValue || !currentValue.trim()) {
      return { parsedJson: null, isValidJson: true, parseError: null };
    }
    try {
      const parsed = JSON.parse(currentValue);
      return { parsedJson: parsed, isValidJson: true, parseError: null };
    } catch (err: any) {
      return {
        parsedJson: null,
        isValidJson: false,
        parseError: err.message || 'Format JSON tidak valid',
      };
    }
  }, [currentValue, language]);

  // Line count & gutter
  const lineCount = useMemo(() => {
    return Math.max(1, (currentValue || '').split('\n').length);
  }, [currentValue]);

  const lineNumbers = useMemo(() => {
    return Array.from({ length: lineCount }, (_, i) => i + 1);
  }, [lineCount]);

  const handleScroll = (e: UIEvent<HTMLTextAreaElement>) => {
    if (gutterRef.current) {
      gutterRef.current.scrollTop = e.currentTarget.scrollTop;
    }
  };

  const handleFormat = (indent = 2) => {
    if (readOnly || language !== 'json') return;
    try {
      const parsed = JSON.parse(currentValue);
      updateContentWithHistory(JSON.stringify(parsed, null, indent));
    } catch {
      // Ignored
    }
  };

  const handleMinify = () => {
    if (readOnly || language !== 'json') return;
    try {
      const parsed = JSON.parse(currentValue);
      updateContentWithHistory(JSON.stringify(parsed));
    } catch {
      // Ignored
    }
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(currentValue);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      // Ignored
    }
  };

  const handleTreeChange = (updated: unknown) => {
    if (readOnly) return;
    try {
      updateContentWithHistory(JSON.stringify(updated, null, 2));
    } catch {
      // Ignored
    }
  };

  // Drag split divider handlers
  const handleSplitMouseDown = (e: ReactMouseEvent) => {
    e.preventDefault();
    setIsDraggingSplit(true);
  };

  const handleSplitTouchStart = (_e: ReactTouchEvent) => {
    setIsDraggingSplit(true);
  };

  useEffect(() => {
    if (!isDraggingSplit) return;

    const handleMove = (clientX: number) => {
      if (!splitContainerRef.current) return;
      const rect = splitContainerRef.current.getBoundingClientRect();
      if (rect.width <= 0) return;
      const rawRatio = ((clientX - rect.left) / rect.width) * 100;
      // Clamp between 15% and 85% so neither panel collapses completely
      const clamped = Math.min(85, Math.max(15, rawRatio));
      setSplitRatio(clamped);
    };

    const handleMouseMove = (e: MouseEvent) => {
      handleMove(e.clientX);
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        handleMove(e.touches[0].clientX);
      }
    };

    const handleEnd = () => {
      setIsDraggingSplit(false);
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleEnd);
    window.addEventListener('touchmove', handleTouchMove, { passive: true });
    window.addEventListener('touchend', handleEnd);

    // Disable text selection and ensure col-resize cursor everywhere during drag
    const originalUserSelect = document.body.style.userSelect;
    const originalCursor = document.body.style.cursor;
    document.body.style.userSelect = 'none';
    document.body.style.cursor = 'col-resize';

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleEnd);
      document.body.style.userSelect = originalUserSelect;
      document.body.style.cursor = originalCursor;
    };
  }, [isDraggingSplit]);

  if (!isOpen || typeof document === 'undefined') return null;

  const isDark = theme === 'dark';

  const modalContent = (
    <div
      className={cn(
        'fixed inset-0 z-50 flex flex-col bg-slate-900/60 backdrop-blur-xs animate-in fade-in duration-150',
        className
      )}
    >
      <div
        className={cn(
          'w-full h-full flex flex-col overflow-hidden shadow-2xl transition-colors',
          isDark ? 'bg-slate-950 text-slate-100' : 'bg-white text-slate-800'
        )}
      >
        {/* Header */}
        <FullScreenHeader
          title={title}
          subtitle={subtitle}
          badge={badge}
          language={language}
          isValidJson={isValidJson}
          viewMode={viewMode}
          onViewModeChange={setViewMode}
          theme={theme}
          onToggleTheme={() => setTheme((t) => (t === 'dark' ? 'light' : 'dark'))}
          readOnly={readOnly}
          onSave={onSave ? () => onSave(currentValue) : undefined}
          onClose={onClose}
        />

        {/* Toolbar */}
        <FullScreenToolbar
          theme={theme}
          readOnly={readOnly}
          historyIndex={historyIndex}
          historyLength={history.length}
          onUndo={handleUndo}
          onRedo={handleRedo}
          language={language}
          isValidJson={isValidJson}
          onFormat={handleFormat}
          onMinify={handleMinify}
          onCopy={handleCopy}
          copied={copied}
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
        />

        {/* Editor & Viewer Body */}
        <div
          ref={splitContainerRef}
          className="flex-1 w-full flex overflow-hidden relative"
        >
          {/* Code Panel */}
          {(viewMode === 'code' || viewMode === 'split') && (
            <div
              className={cn(
                'h-full flex overflow-hidden relative transition-colors',
                viewMode === 'split' ? 'shrink-0' : 'w-full',
                isDraggingSplit && 'pointer-events-none select-none'
              )}
              style={
                viewMode === 'split'
                  ? { width: `calc(${splitRatio}% - 5px)` }
                  : undefined
              }
            >
              {/* Line Numbers Gutter */}
              <CodeGutter gutterRef={gutterRef} lineNumbers={lineNumbers} theme={theme} />

              {/* Textarea Area */}
              <div className="flex-1 relative h-full">
                <textarea
                  ref={textareaRef}
                  value={currentValue}
                  onChange={(e) => updateContentWithHistory(e.target.value)}
                  onKeyDown={handleEditorKeyDown}
                  onScroll={handleScroll}
                  readOnly={readOnly}
                  spellCheck={false}
                  className={cn(
                    'w-full h-full p-3 font-mono text-xs leading-relaxed resize-none focus:outline-none focus:ring-0 border-0 overflow-auto whitespace-pre tab-[2] transition-colors',
                    isDark
                      ? 'text-slate-100 bg-transparent placeholder-slate-600'
                      : 'text-slate-900 bg-white placeholder-slate-400',
                    readOnly ? 'cursor-default' : 'cursor-text'
                  )}
                />
              </div>
            </div>
          )}

          {/* Draggable Splitter Handle */}
          {viewMode === 'split' && (
            <SplitterHandle
              theme={theme}
              isDragging={isDraggingSplit}
              onMouseDown={handleSplitMouseDown}
              onTouchStart={handleSplitTouchStart}
              onDoubleClick={() => setSplitRatio(50)}
            />
          )}

          {/* Tree Panel */}
          {(viewMode === 'tree' || viewMode === 'split') && (
            <div
              className={cn(
                'h-full overflow-auto p-2 transition-colors',
                isDark ? 'bg-slate-950/90' : 'bg-slate-50/70',
                viewMode === 'split' ? 'shrink-0' : 'w-full',
                isDraggingSplit && 'pointer-events-none select-none'
              )}
              style={
                viewMode === 'split'
                  ? { width: `calc(${100 - splitRatio}% - 5px)` }
                  : undefined
              }
            >
              {isValidJson && parsedJson !== null ? (
                <div
                  className={cn(
                    'rounded-xl shadow-xs overflow-hidden border transition-colors',
                    isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'
                  )}
                >
                  <JsonTreeViewer
                    data={parsedJson}
                    onChange={handleTreeChange}
                    readOnly={readOnly}
                    theme={theme}
                    searchTerm={searchTerm}
                  />
                </div>
              ) : (
                <div
                  className={cn(
                    'flex flex-col items-center justify-center h-full p-8 text-center gap-2 select-none',
                    isDark ? 'text-slate-400' : 'text-slate-500'
                  )}
                >
                  <AlertCircle className="w-8 h-8 text-amber-500" />
                  <p className={cn('text-sm font-medium', isDark ? 'text-slate-200' : 'text-slate-700')}>
                    Tree view unavailable
                  </p>
                  <p className="text-xs max-w-sm">
                    {parseError || 'Fix JSON syntax errors in the code editor to enable the tree view.'}
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Status Bar Footer */}
        <FullScreenStatusBar
          theme={theme}
          lineCount={lineCount}
          charCount={currentValue.length}
          language={language}
          isValidJson={isValidJson}
          parseError={parseError}
        />
      </div>
    </div>
  );

  return createPortal(modalContent, document.body);
}

export const FullScreenJsonEditor = FullScreenCodeEditor;

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  FullScreenCodeEditorProps,
  FullScreenJsonEditorProps,
} from '../../../types/ui/code-editor.types';
