import { LayoutBackdrop } from './LayoutBackdrop';
import { LayoutBody } from './LayoutBody';
import { LayoutContent } from './LayoutContent';
import { LayoutHeader } from './LayoutHeader';
import { LayoutLoading } from './LayoutLoading';
import { LayoutSidebar } from './LayoutSidebar';
import { StackLayer } from './StackLayer';

import { cn } from '../../../utils/ui/cn';

import type { LayoutProps } from '../../../types/ui/layout.types';

export function Layout({
  theme = 'light',
  fullScreen = true,
  className = '',
  children,
}: LayoutProps) {
  const isDark = theme === 'dark';

  return (
    <div
      data-theme={theme}
      className={cn(
        'relative flex flex-col font-sans transition-colors',
        fullScreen ? 'h-screen w-screen overflow-hidden' : 'w-full h-full',
        isDark ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900',
        className
      )}
    >
      {children}
    </div>
  );
}

// Compound component attachments
Layout.Header = LayoutHeader;
Layout.Body = LayoutBody;
Layout.Sidebar = LayoutSidebar;
Layout.Content = LayoutContent;
Layout.Backdrop = LayoutBackdrop;
Layout.Loading = LayoutLoading;
Layout.Layer = StackLayer;

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { LayoutProps } from '../../../types/ui/layout.types';
