import type { EmptyStateProps } from '../../../types/ui/emptyState.types';

export function EmptyState({
  icon,
  title,
  description,
  action,
  compact = false,
  theme = 'light',
  className = '',
}: EmptyStateProps) {
  const isDark = theme === 'dark';

  return (
    <div
      className={`flex flex-col items-center justify-center text-center rounded-xl select-none ${
        isDark ? 'bg-slate-950/60 text-slate-300' : 'bg-slate-50/40 text-slate-700'
      } ${compact ? 'p-4 sm:p-5 gap-2' : 'p-8 sm:p-12 gap-3'} ${className}`}
    >
      {icon && (
        <div
          className={`rounded-xl shadow-2xs flex items-center justify-center shrink-0 ${
            isDark
              ? 'bg-slate-900 border border-slate-800 text-slate-400'
              : 'bg-white border border-slate-200/70 text-slate-400'
          } ${compact ? 'w-8 h-8' : 'w-11 h-11'}`}
        >
          {icon}
        </div>
      )}
      <div className="max-w-xs space-y-0.5">
        <h4 className={`text-xs sm:text-sm font-semibold tracking-tight leading-snug ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>
          {title}
        </h4>
        {description && (
          <p className={`text-[11px] sm:text-xs leading-relaxed ${isDark ? 'text-slate-400' : 'text-slate-400'}`}>
            {description}
          </p>
        )}
      </div>
      {action && <div className="mt-1">{action}</div>}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { EmptyStateProps } from '../../../types/ui/emptyState.types';
