import { useSyncExternalStore } from 'react';
import type { ReactNode } from 'react';

import type {
  ToastData,
  ToastOptions,
  ToastPromiseMessages,
} from '../../../types/ui/toast.types';

type Listener = () => void;

class ToastManager {
  private toasts: ToastData[] = [];
  private listeners: Set<Listener> = new Set();
  private timers: Map<string, ReturnType<typeof setTimeout>> = new Map();

  private emitChange() {
    for (const listener of this.listeners) {
      listener();
    }
  }

  public subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  public getSnapshot = (): ToastData[] => {
    return this.toasts;
  };

  public add(title: ReactNode, options: ToastOptions = {}): string {
    const id = options.id || `toast-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const duration = options.duration ?? options.durationMs ?? (options.type === 'loading' ? Infinity : 4000);

    const newToast: ToastData = {
      id,
      title,
      type: options.type || 'default',
      description: options.description,
      msg: typeof title === 'string' ? title : undefined,
      duration,
      durationMs: duration,
      icon: options.icon,
      action: options.action,
      cancel: options.cancel,
      dismissible: options.dismissible ?? true,
      className: options.className,
      createdAt: Date.now(),
    };

    // If toast with this id already exists, update it (useful for promise loading -> success)
    const existingIndex = this.toasts.findIndex((t) => t.id === id);
    if (existingIndex > -1) {
      this.toasts[existingIndex] = { ...this.toasts[existingIndex], ...newToast };
    } else {
      // Keep up to 10 latest toasts in memory
      this.toasts = [...this.toasts.slice(-9), newToast];
    }

    this.clearTimer(id);

    if (duration !== Infinity && duration > 0) {
      const timer = setTimeout(() => {
        this.dismiss(id);
      }, duration);
      this.timers.set(id, timer);
    }

    this.emitChange();
    return id;
  }

  public dismiss(id?: string): void {
    if (id) {
      this.clearTimer(id);
      this.toasts = this.toasts.filter((t) => t.id !== id);
    } else {
      for (const timer of this.timers.values()) {
        clearTimeout(timer);
      }
      this.timers.clear();
      this.toasts = [];
    }
    this.emitChange();
  }

  private clearTimer(id: string) {
    const timer = this.timers.get(id);
    if (timer) {
      clearTimeout(timer);
      this.timers.delete(id);
    }
  }
}

export const toastManager = new ToastManager();

export interface ToastCallable {
  (title: ReactNode, options?: ToastOptions): string;
  success: (title: ReactNode, options?: ToastOptions) => string;
  error: (title: ReactNode, options?: ToastOptions) => string;
  warning: (title: ReactNode, options?: ToastOptions) => string;
  info: (title: ReactNode, options?: ToastOptions) => string;
  loading: (title: ReactNode, options?: ToastOptions) => string;
  promise: <T>(
    promise: Promise<T> | (() => Promise<T>),
    messages: ToastPromiseMessages<T>,
    options?: ToastOptions
  ) => Promise<T>;
  dismiss: (id?: string) => void;
}

export const toast: ToastCallable = Object.assign(
  (title: ReactNode, options?: ToastOptions) => {
    return toastManager.add(title, options);
  },
  {
    success: (title: ReactNode, options?: ToastOptions) => {
      return toastManager.add(title, { ...options, type: 'success' });
    },
    error: (title: ReactNode, options?: ToastOptions) => {
      return toastManager.add(title, { ...options, type: 'error' });
    },
    warning: (title: ReactNode, options?: ToastOptions) => {
      return toastManager.add(title, { ...options, type: 'warning' });
    },
    info: (title: ReactNode, options?: ToastOptions) => {
      return toastManager.add(title, { ...options, type: 'info' });
    },
    loading: (title: ReactNode, options?: ToastOptions) => {
      return toastManager.add(title, { ...options, type: 'loading', duration: Infinity });
    },
    promise: async <T>(
      promise: Promise<T> | (() => Promise<T>),
      messages: ToastPromiseMessages<T>,
      options?: ToastOptions
    ): Promise<T> => {
      const id = toastManager.add(messages.loading, {
        ...options,
        type: 'loading',
        duration: Infinity,
      });

      try {
        const p = typeof promise === 'function' ? promise() : promise;
        const result = await p;
        const successMessage =
          typeof messages.success === 'function'
            ? messages.success(result)
            : messages.success;

        toastManager.add(successMessage, {
          ...options,
          id,
          type: 'success',
          duration: options?.duration ?? 4000,
        });

        return result;
      } catch (err: any) {
        const errorMessage =
          typeof messages.error === 'function' ? messages.error(err) : messages.error;

        toastManager.add(errorMessage, {
          ...options,
          id,
          type: 'error',
          duration: options?.duration ?? 5000,
        });

        throw err;
      }
    },
    dismiss: (id?: string) => {
      toastManager.dismiss(id);
    },
  }
);

export function useToastStore(): ToastData[] {
  return useSyncExternalStore(
    (listener) => toastManager.subscribe(listener),
    toastManager.getSnapshot,
    () => []
  );
}

export function useToast() {
  const toasts = useToastStore();
  return {
    toasts,
    toast,
    dismiss: toast.dismiss,
  };
}
