import { forwardRef, useId } from 'react';

import { cn } from '../../../../utils/ui/cn';

import type { RadioProps } from '../../../../types/ui/field/radio.types';

export const Radio = forwardRef<HTMLInputElement, RadioProps>(
  (
    {
      id: customId,
      value,
      checked = false,
      onChange,
      label,
      description,
      disabled = false,
      size = 'md',
      variant = 'default',
      className,
      wrapperClassName,
      ...props
    },
    ref
  ) => {
    const generatedId = useId();
    const inputId = customId || generatedId;

    const circleSizeClasses = {
      sm: 'w-4 h-4',
      md: 'w-5 h-5',
      lg: 'w-6 h-6',
    }[size];

    const innerDotClasses = {
      sm: 'w-1.5 h-1.5',
      md: 'w-2 h-2',
      lg: 'w-2.5 h-2.5',
    }[size];

    const isCard = variant === 'card';

    return (
      <label
        htmlFor={inputId}
        className={cn(
          'relative flex items-start gap-3 select-none transition-all cursor-pointer',
          isCard &&
            cn(
              'p-3.5 rounded-xl border bg-slate-50/60 hover:bg-slate-50 transition-colors',
              checked ? 'border-emerald-500 bg-emerald-50/30 ring-1 ring-emerald-500/20' : 'border-slate-200'
            ),
          disabled && 'opacity-60 cursor-not-allowed hover:bg-transparent',
          wrapperClassName
        )}
      >
        <div className="relative flex items-center pt-0.5">
          <input
            ref={ref}
            id={inputId}
            type="radio"
            value={value}
            checked={checked}
            onChange={() => onChange?.(value)}
            disabled={disabled}
            className="sr-only peer"
            {...props}
          />
          <div
            className={cn(
              'rounded-full border flex items-center justify-center transition-all duration-150 shadow-2xs peer-focus-visible:ring-2 peer-focus-visible:ring-emerald-500/40 peer-focus-visible:ring-offset-1',
              circleSizeClasses,
              checked
                ? 'bg-emerald-600 border-emerald-600'
                : 'bg-white border-slate-300 hover:border-slate-400',
              disabled && 'bg-slate-100 border-slate-300 cursor-not-allowed',
              className
            )}
          >
            {checked && <div className={cn('rounded-full bg-white', innerDotClasses)} />}
          </div>
        </div>

        {(label || description) && (
          <div className="flex flex-col">
            {label && (
              <span
                className={cn(
                  'font-medium text-slate-800 transition-colors leading-snug',
                  size === 'sm' ? 'text-xs' : size === 'lg' ? 'text-base' : 'text-sm',
                  disabled && 'text-slate-400'
                )}
              >
                {label}
              </span>
            )}
            {description && (
              <span
                className={cn(
                  'text-slate-500 text-xs mt-0.5 leading-normal',
                  disabled && 'text-slate-400'
                )}
              >
                {description}
              </span>
            )}
          </div>
        )}
      </label>
    );
  }
);

Radio.displayName = 'Radio';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { RadioProps } from '../../../../types/ui/field/radio.types';
