import { forwardRef } from 'react';

import { FieldWrapper } from '../field-wrapper';
import { Checkbox } from './Checkbox';

import { cn } from '../../../../utils/ui/cn';

import type { CheckboxGroupProps } from '../../../../types/ui/field/checkbox.types';

export const CheckboxGroup = forwardRef<HTMLDivElement, CheckboxGroupProps>(
  (
    {
      options,
      value = [],
      onChange,
      name,
      label,
      error,
      helperText,
      hint,
      required,
      optional,
      orientation = 'vertical',
      size = 'md',
      variant = 'default',
      disabled = false,
      className,
      ...props
    },
    ref
  ) => {
    const handleCheckboxChange = (optValue: string, checked: boolean) => {
      if (checked) {
        onChange?.([...value, optValue]);
      } else {
        onChange?.(value.filter((v) => v !== optValue));
      }
    };

    const isHorizontal = orientation === 'horizontal';

    const groupNode = (
      <div
        ref={ref}
        role="group"
        className={cn(
          isHorizontal ? 'flex flex-wrap items-center gap-4' : 'flex flex-col space-y-2.5',
          className
        )}
        {...props}
      >
        {options.map((option) => (
          <Checkbox
            key={option.value}
            name={name}
            checked={value.includes(option.value)}
            onChange={(checked) => handleCheckboxChange(option.value, checked)}
            label={option.label}
            description={option.description}
            disabled={disabled || option.disabled}
            size={size}
            variant={variant}
          />
        ))}
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={size}
        >
          {groupNode}
        </FieldWrapper>
      );
    }

    return groupNode;
  }
);

CheckboxGroup.displayName = 'CheckboxGroup';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { CheckboxGroupProps, CheckboxOption } from '../../../../types/ui/field/checkbox.types';
