import { forwardRef, useEffect, useId, useMemo, useRef, useState } from 'react';
import { Check, ChevronDown, Search, X } from 'lucide-react';

import { FieldWrapper } from '../field-wrapper';

import { cn } from '../../../../utils/ui/cn';

import type { MultiSelectProps, SelectOption } from '../../../../types/ui/field/select.types';

export const MultiSelect = forwardRef<HTMLButtonElement, MultiSelectProps>(
  (
    {
      options,
      value = [],
      onChange,
      placeholder = 'Pilih beberapa opsi...',
      label,
      error,
      helperText,
      hint,
      required,
      optional,
      disabled,
      size = 'md',
      layout = 'vertical',
      searchable = true,
      searchPlaceholder = 'Cari...',
      clearable = true,
      maxDisplayTags = 3,
      emptyText = 'Tidak ada opsi tersedia',
      className,
      wrapperClassName,
    },
    ref
  ) => {
    const generatedId = useId();
    const containerRef = useRef<HTMLDivElement>(null);
    const searchInputRef = useRef<HTMLInputElement>(null);

    const [isOpen, setIsOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');

    const normalizedOptions: SelectOption[] = useMemo(() => {
      return options.map((opt) => (typeof opt === 'string' ? { label: opt, value: opt } : opt));
    }, [options]);

    const selectedOptions = useMemo(() => {
      return normalizedOptions.filter((opt) => value.includes(opt.value));
    }, [normalizedOptions, value]);

    const filteredOptions = useMemo(() => {
      if (!searchable || !searchQuery.trim()) return normalizedOptions;
      const q = searchQuery.toLowerCase();
      return normalizedOptions.filter(
        (opt) => opt.label.toLowerCase().includes(q) || (opt.description && opt.description.toLowerCase().includes(q))
      );
    }, [normalizedOptions, searchable, searchQuery]);

    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
          setIsOpen(false);
          setSearchQuery('');
        }
      };

      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
      if (isOpen && searchable) {
        setTimeout(() => searchInputRef.current?.focus(), 50);
      }
    }, [isOpen, searchable]);

    const handleToggle = (optValue: string) => {
      const newValues = value.includes(optValue)
        ? value.filter((v) => v !== optValue)
        : [...value, optValue];
      onChange?.(newValues);
    };

    const handleRemoveTag = (e: React.MouseEvent, optValue: string) => {
      e.stopPropagation();
      onChange?.(value.filter((v) => v !== optValue));
    };

    const handleClearAll = (e: React.MouseEvent) => {
      e.stopPropagation();
      onChange?.([]);
    };

    const handleSelectAll = () => {
      const allSelectable = normalizedOptions.filter((o) => !o.disabled).map((o) => o.value);
      onChange?.(allSelectable);
    };

    const sizeClasses = {
      sm: 'py-1.5 px-3 text-xs min-h-[34px]',
      md: 'py-2 px-3 text-sm min-h-[42px]',
      lg: 'py-2.5 px-4 text-base min-h-[48px]',
    }[size];

    const multiSelectNode = (
      <div ref={containerRef} className="relative w-full">
        <button
          ref={ref}
          id={generatedId}
          type="button"
          onClick={() => !disabled && setIsOpen((prev) => !prev)}
          disabled={disabled}
          className={cn(
            'w-full flex items-center justify-between text-left transition-colors rounded-lg focus:outline-none cursor-pointer',
            sizeClasses,
            error
              ? 'bg-rose-50/20 border border-rose-300 focus:border-rose-500 focus:ring-1 focus:ring-rose-500 text-rose-900'
              : 'bg-white hover:border-slate-400 focus:border-emerald-600 focus:ring-1 focus:ring-emerald-600 border border-slate-300',
            disabled && 'opacity-60 bg-slate-50/80 cursor-not-allowed border-slate-200',
            className
          )}
          aria-haspopup="listbox"
          aria-expanded={isOpen}
        >
          <div className="flex flex-wrap items-center gap-1.5 overflow-hidden">
            {selectedOptions.length === 0 ? (
              <span className="text-slate-400 select-none">{placeholder}</span>
            ) : (
              <>
                {selectedOptions.slice(0, maxDisplayTags).map((opt) => (
                  <span
                    key={opt.value}
                    className="inline-flex items-center gap-1 px-2 py-0.5 bg-emerald-50 text-emerald-800 border border-emerald-200/60 rounded-md text-xs font-medium"
                  >
                    <span>{opt.label}</span>
                    {!disabled && (
                      <span
                        role="button"
                        onClick={(e) => handleRemoveTag(e, opt.value)}
                        className="p-0.5 hover:bg-emerald-100 rounded text-emerald-600 hover:text-emerald-900 transition-colors"
                      >
                        <X className="w-3 h-3" />
                      </span>
                    )}
                  </span>
                ))}
                {selectedOptions.length > maxDisplayTags && (
                  <span className="px-1.5 py-0.5 bg-slate-200 text-slate-700 rounded-md text-[11px] font-semibold">
                    +{selectedOptions.length - maxDisplayTags} lainnya
                  </span>
                )}
              </>
            )}
          </div>

          <div className="flex items-center gap-1.5 ml-2 shrink-0">
            {clearable && selectedOptions.length > 0 && !disabled && (
              <span
                role="button"
                onClick={handleClearAll}
                className="p-0.5 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-200/60 transition-colors cursor-pointer"
                aria-label="Bersihkan semua"
              >
                <X className="w-3.5 h-3.5" />
              </span>
            )}
            <ChevronDown
              className={cn('w-4 h-4 text-slate-400 transition-transform duration-200', isOpen && 'rotate-180')}
            />
          </div>
        </button>

        {isOpen && (
          <div className="absolute z-50 w-full mt-1.5 bg-white border border-slate-200 rounded-lg shadow-xl overflow-hidden animate-in fade-in zoom-in-95 duration-100 max-h-72 flex flex-col">
            {searchable && (
              <div className="p-2 border-b border-slate-100">
                <div className="relative flex items-center">
                  <Search className="w-3.5 h-3.5 absolute left-2.5 text-slate-400 pointer-events-none" />
                  <input
                    ref={searchInputRef}
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder={searchPlaceholder}
                    className="w-full pl-8 pr-3 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-lg text-slate-800 focus:outline-none focus:border-emerald-500 focus:bg-white"
                  />
                </div>
              </div>
            )}

            <div className="flex items-center justify-between px-3 py-1.5 bg-slate-50 border-b border-slate-100 text-[11px]">
              <button
                type="button"
                onClick={handleSelectAll}
                className="text-emerald-600 hover:text-emerald-700 font-medium cursor-pointer"
              >
                Pilih Semua
              </button>
              <button
                type="button"
                onClick={handleClearAll}
                className="text-slate-500 hover:text-slate-700 cursor-pointer"
              >
                Hapus Semua ({value.length})
              </button>
            </div>

            <div className="overflow-y-auto p-1 max-h-52">
              {filteredOptions.length === 0 ? (
                <div className="px-4 py-3 text-xs text-slate-500 text-center select-none">{emptyText}</div>
              ) : (
                <ul role="listbox">
                  {filteredOptions.map((option) => {
                    const isSelected = value.includes(option.value);

                    return (
                      <li
                        key={option.value}
                        role="option"
                        aria-selected={isSelected}
                        onClick={() => handleToggle(option.value)}
                        className={cn(
                          'flex items-center gap-2.5 px-3 py-2 text-xs md:text-sm rounded-lg cursor-pointer transition-colors select-none',
                          isSelected
                            ? 'bg-emerald-50/70 text-emerald-950 font-medium'
                            : 'text-slate-700 hover:bg-slate-100 hover:text-slate-900',
                          option.disabled && 'opacity-40 cursor-not-allowed hover:bg-transparent'
                        )}
                      >
                        <div
                          className={cn(
                            'w-4 h-4 rounded border flex items-center justify-center transition-colors shrink-0',
                            isSelected
                              ? 'bg-emerald-600 border-emerald-600 text-white'
                              : 'border-slate-300 bg-white'
                          )}
                        >
                          {isSelected && <Check className="w-3 h-3 stroke-[3]" />}
                        </div>

                        <div className="flex flex-col truncate">
                          <span className="truncate">{option.label}</span>
                          {option.description && (
                            <span className="text-[11px] text-slate-400 font-normal truncate">
                              {option.description}
                            </span>
                          )}
                        </div>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>
          </div>
        )}
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          htmlFor={generatedId}
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={size}
          layout={layout}
          className={wrapperClassName}
        >
          {multiSelectNode}
        </FieldWrapper>
      );
    }

    return multiSelectNode;
  }
);

MultiSelect.displayName = 'MultiSelect';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { MultiSelectProps, SelectOption } from '../../../../types/ui/field/select.types';
