import { useEffect } from 'react';
import { Loader2 } from 'lucide-react';

import { cn } from '../../../utils/ui/cn';

import { STACK_LAYER_CLASSES } from '../../../types/ui/layout.types';
import type { LayoutLoadingProps } from '../../../types/ui/layout.types';

export function LayoutLoading({
  visible = false,
  message = 'Loading...',
  description,
  variant = 'spinner',
  progress,
  blur = true,
  layer = 'loading',
  customIcon,
  className = '',
}: LayoutLoadingProps) {
  // Lock body scroll when loading overlay is active
  useEffect(() => {
    if (!visible) return;

    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    return () => {
      document.body.style.overflow = originalOverflow;
    };
  }, [visible]);

  if (!visible) return null;

  const layerClass = STACK_LAYER_CLASSES[layer] || 'z-[100]';

  return (
    <div
      role="status"
      aria-live="polite"
      aria-label={typeof message === 'string' ? message : 'Loading'}
      className={cn(
        'fixed inset-0 flex items-center justify-center p-4 select-none',
        'bg-slate-950/60 text-white transition-all duration-300 animate-in fade-in',
        blur && 'backdrop-blur-sm',
        layerClass,
        className
      )}
    >
      {/* Top progress bar variant */}
      {variant === 'bar' && (
        <div className="fixed top-0 left-0 right-0 h-1 bg-slate-800 overflow-hidden">
          <div
            className="h-full bg-emerald-500 transition-all duration-300"
            style={{
              width: progress !== undefined ? `${Math.min(100, Math.max(0, progress))}%` : '100%',
              animation: progress === undefined ? 'pulse 1.5s ease-in-out infinite' : undefined,
            }}
          />
        </div>
      )}

      {/* Center card */}
      <div className="flex flex-col items-center justify-center gap-3 p-6 max-w-sm rounded-2xl bg-slate-900/90 border border-slate-800 shadow-2xl text-center">
        {/* Spinner or Custom Icon */}
        <div className="relative flex items-center justify-center">
          <div className="absolute inset-0 rounded-full bg-emerald-500/20 blur-md animate-pulse" />
          {customIcon ? (
            <div className="relative z-10">{customIcon}</div>
          ) : (
            <Loader2 className="relative z-10 w-8 h-8 text-emerald-400 animate-spin" />
          )}
        </div>

        {/* Message */}
        {message && (
          <h3 className="text-sm font-semibold text-slate-100 tracking-tight">
            {message}
          </h3>
        )}

        {/* Optional Description */}
        {description && (
          <p className="text-xs text-slate-400 max-w-xs leading-relaxed">
            {description}
          </p>
        )}

        {/* Progress percent badge */}
        {progress !== undefined && (
          <div className="w-full flex flex-col gap-1.5 mt-1">
            <div className="w-full h-1.5 rounded-full bg-slate-800 overflow-hidden">
              <div
                className="h-full bg-emerald-500 transition-all duration-300 rounded-full"
                style={{ width: `${Math.min(100, Math.max(0, progress))}%` }}
              />
            </div>
            <span className="text-[10px] font-mono text-emerald-400">
              {Math.round(progress)}%
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { LayoutLoadingProps } from '../../../types/ui/layout.types';
