import type { FeatureBannerProps } from '../../../types/ui/card.types';
import { Card } from './index';

export function FeatureBanner({
  icon,
  iconBgColor = 'bg-emerald-50 text-[#1b7e2e] border-emerald-200',
  title,
  badge,
  description,
  actionSlot,
  actions,
  tone = 'emerald',
  className = '',
  ...props
}: FeatureBannerProps) {
  const actionContent = actions || actionSlot;
  const toneClasses = tone === 'emerald'
    ? 'bg-gradient-to-br from-white via-emerald-50/40 to-emerald-50/20 border-emerald-200/90 text-slate-900 shadow-xs'
    : tone === 'slate'
    ? 'bg-gradient-to-br from-white via-slate-50 to-slate-100/50 border-slate-200 text-slate-900 shadow-xs'
    : 'bg-white border-slate-200 text-slate-900 shadow-xs';

  return (
    <Card
      {...props}
      padding="large"
      className={`relative overflow-hidden ${toneClasses} ${className}`}
    >
      <div className="relative z-10 flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div className="flex items-start gap-3.5 min-w-0">
          {icon && (
            <div className={`p-2.5 rounded-xl border shadow-2xs shrink-0 ${iconBgColor}`}>
              {icon}
            </div>
          )}
          <div className="space-y-1 min-w-0">
            <div className="flex items-center gap-2.5 flex-wrap">
              <h2 className="text-lg md:text-xl font-bold tracking-tight text-slate-900">
                {title}
              </h2>
              {badge}
            </div>
            {description && (
              <div className="text-xs md:text-sm text-slate-600 leading-relaxed max-w-3xl">
                {description}
              </div>
            )}
          </div>
        </div>

        {actionContent && (
          <div className="flex items-center gap-2 md:shrink-0 flex-wrap">
            {actionContent}
          </div>
        )}
      </div>
    </Card>
  );
}
