import { AlertCircle, Check } from 'lucide-react';

import { cn } from '../../../utils/ui/cn';

import type { CodeEditorTheme } from '../../../types/ui/code-editor.types';

export function FullScreenStatusBar({
  theme,
  lineCount,
  charCount,
  language,
  isValidJson,
  parseError,
}: FullScreenStatusBarProps) {
  const isDark = theme === 'dark';

  return (
    <div
      className={cn(
        'flex items-center justify-between px-4 py-1.5 border-t text-xs shrink-0 font-mono select-none transition-colors',
        isDark
          ? 'bg-slate-900 border-slate-800 text-slate-400'
          : 'bg-slate-100 border-slate-200 text-slate-600'
      )}
    >
      <div className="flex items-center gap-3">
        <span>Lines: {lineCount}</span>
        <span>Chars: {charCount}</span>
        <span className="capitalize">Language: {language}</span>
      </div>

      <div className="flex items-center gap-2">
        {!isValidJson && parseError && (
          <span className="text-rose-500 flex items-center gap-1 font-sans font-medium">
            <AlertCircle className="w-3.5 h-3.5" />
            <span className="truncate max-w-md">{parseError}</span>
          </span>
        )}
        {isValidJson && (
          <span className="text-emerald-500 flex items-center gap-1 font-sans font-medium">
            <Check className="w-3.5 h-3.5" />
            <span>Ready</span>
          </span>
        )}
      </div>
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface FullScreenStatusBarProps {
  theme: CodeEditorTheme;
  lineCount: number;
  charCount: number;
  language: string;
  isValidJson: boolean;
  parseError: string | null;
}
