import { GripVertical } from 'lucide-react';

import { cn } from '../../../utils/ui/cn';

import type { CodeEditorTheme } from '../../../types/ui/code-editor.types';

export function SplitterHandle({
  theme,
  isDragging,
  onMouseDown,
  onTouchStart,
  onDoubleClick,
  className = '',
}: SplitterHandleProps) {
  const isDark = theme === 'dark';

  return (
    <div
      role="separator"
      tabIndex={0}
      aria-orientation="vertical"
      aria-label="Resize panels divider"
      onMouseDown={onMouseDown}
      onTouchStart={onTouchStart}
      onDoubleClick={onDoubleClick}
      title="Drag to resize panels (Double-click to reset to 50%)"
      className={cn(
        'relative group shrink-0 w-2.5 h-full flex items-center justify-center cursor-col-resize select-none transition-colors z-10',
        isDark ? 'bg-slate-950 hover:bg-slate-900' : 'bg-slate-100 hover:bg-slate-200',
        isDragging && (isDark ? 'bg-slate-900' : 'bg-slate-200'),
        className
      )}
    >
      {/* Visual Divider Line */}
      <div
        className={cn(
          'w-px h-full transition-colors',
          isDragging
            ? 'bg-emerald-500 ring-1 ring-emerald-500/50'
            : isDark
            ? 'bg-slate-800 group-hover:bg-emerald-500'
            : 'bg-slate-200 group-hover:bg-emerald-500'
        )}
      />

      {/* Grip Handle Pill */}
      <div
        className={cn(
          'absolute top-1/2 -translate-y-1/2 w-4 h-8 rounded-full flex items-center justify-center border shadow-xs transition-all pointer-events-none',
          isDragging
            ? 'bg-emerald-600 border-emerald-400 text-white scale-110'
            : isDark
            ? 'bg-slate-800 border-slate-700 text-slate-400 group-hover:bg-slate-700 group-hover:text-emerald-400 group-hover:border-emerald-500/60'
            : 'bg-white border-slate-300 text-slate-500 group-hover:bg-slate-50 group-hover:text-emerald-600 group-hover:border-emerald-500/60'
        )}
      >
        <GripVertical className="w-3 h-3" />
      </div>
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface SplitterHandleProps {
  theme: CodeEditorTheme;
  isDragging: boolean;
  onMouseDown: (e: React.MouseEvent) => void;
  onTouchStart: (e: React.TouchEvent) => void;
  onDoubleClick: () => void;
  className?: string;
}
