import { useMemo, useState } from 'react';
import { ArrowDown, ArrowUp, ArrowUpDown, Loader2 } from 'lucide-react';

import { EmptyState } from '../empty-state';

import { cn } from '../../../utils/ui/cn';

import type { TableProps, TableSize } from '../../../types/ui/table.types';

const sizeHeaderStyles: Record<TableSize, string> = {
  sm: 'py-2 px-3 text-[10px]',
  md: 'py-3 px-3.5 text-[11px]',
  lg: 'py-3.5 px-4 text-xs',
};

const sizeBodyStyles: Record<TableSize, string> = {
  sm: 'py-1.5 px-3 text-xs',
  md: 'py-2.5 px-3.5 text-sm',
  lg: 'py-3.5 px-4 text-sm',
};

export function Table<T>({
  data,
  columns,
  rowKey,
  emptyTitle = 'Tidak Ada Data',
  emptyMessage = 'No data available',
  emptyIcon,
  defaultSortKey,
  defaultSortDirection = 'asc',
  className = '',
  tableClassName = '',
  stickyHeader = true,
  size = 'md',
  isLoading = false,
  loadingMessage = 'Memuat data...',
  onRowClick,
  rowClassName,
  bordered = false,
  striped = false,
}: TableProps<T>) {
  const [sortKey, setSortKey] = useState<string | null>(defaultSortKey || null);
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>(defaultSortDirection);

  const handleSort = (columnKey: string, sortable?: boolean) => {
    if (!sortable) return;
    if (sortKey === columnKey) {
      if (sortDirection === 'asc') {
        setSortDirection('desc');
      } else {
        setSortKey(null);
        setSortDirection('asc');
      }
    } else {
      setSortKey(columnKey);
      setSortDirection('asc');
    }
  };

  const sortedData = useMemo(() => {
    if (!sortKey) return data;
    const col = columns.find((c) => c.key === sortKey);
    if (!col) return data;

    return [...data].sort((a, b) => {
      let valA: any = col.sortValue ? col.sortValue(a) : (a as any)[sortKey];
      let valB: any = col.sortValue ? col.sortValue(b) : (b as any)[sortKey];

      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();

      if (valA === valB) return 0;
      if (valA === null || valA === undefined) return 1;
      if (valB === null || valB === undefined) return -1;

      const compare = valA > valB ? 1 : -1;
      return sortDirection === 'asc' ? compare : -compare;
    });
  }, [data, sortKey, sortDirection, columns]);

  return (
    <div
      className={cn(
        'w-full overflow-x-auto rounded-2xl border border-slate-200/90 bg-white shadow-2xs',
        className
      )}
    >
      <table className={cn('w-full text-left border-collapse', tableClassName)}>
        <thead>
          <tr
            className={cn(
              'border-b border-slate-200 font-semibold text-slate-500 uppercase tracking-wider bg-slate-50/95 backdrop-blur-xs select-none',
              stickyHeader ? 'sticky top-0 z-10' : '',
              sizeHeaderStyles[size]
            )}
          >
            {columns.map((col) => {
              const isSorted = sortKey === col.key;
              const stickyClasses =
                col.sticky === 'left'
                  ? 'sticky left-0 z-20 bg-slate-50 shadow-[1px_0_0_0_rgb(226,232,240)]'
                  : col.sticky === 'right'
                  ? 'sticky right-0 z-20 bg-slate-50 shadow-[-1px_0_0_0_rgb(226,232,240)]'
                  : '';

              return (
                <th
                  key={col.key}
                  style={{ width: col.width }}
                  className={cn(
                    sizeHeaderStyles[size],
                    'transition-colors',
                    stickyClasses,
                    col.sortable ? 'cursor-pointer hover:bg-slate-100/90' : '',
                    col.headerClassName
                  )}
                  onClick={() => handleSort(col.key, col.sortable)}
                >
                  <div
                    className={cn(
                      'flex items-center gap-1.5',
                      col.align === 'center'
                        ? 'justify-center'
                        : col.align === 'right'
                        ? 'justify-end'
                        : 'justify-start'
                    )}
                  >
                    <span>{col.title}</span>
                    {col.sortable && (
                      <span className="shrink-0 text-slate-400">
                        {isSorted ? (
                          sortDirection === 'asc' ? (
                            <ArrowUp className="w-3.5 h-3.5 text-emerald-600" />
                          ) : (
                            <ArrowDown className="w-3.5 h-3.5 text-emerald-600" />
                          )
                        ) : (
                          <ArrowUpDown className="w-3 h-3 text-slate-300 opacity-60" />
                        )}
                      </span>
                    )}
                  </div>
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100 text-slate-700">
          {isLoading ? (
            <tr>
              <td colSpan={columns.length} className="py-12 px-4 text-center">
                <div className="flex flex-col items-center justify-center gap-2.5 text-slate-500">
                  <Loader2 className="w-6 h-6 animate-spin text-emerald-600" />
                  <span className="text-xs font-medium">{loadingMessage}</span>
                </div>
              </td>
            </tr>
          ) : sortedData.length === 0 ? (
            <tr>
              <td colSpan={columns.length} className="py-8 px-4 text-center">
                <EmptyState
                  compact
                  className="!border-0 !bg-transparent"
                  icon={emptyIcon}
                  title={emptyTitle}
                  description={emptyMessage}
                />
              </td>
            </tr>
          ) : (
            sortedData.map((record, index) => {
              const key = rowKey ? rowKey(record, index) : (record as any)?.id || index;
              const isClickable = Boolean(onRowClick);
              const customRowClass =
                typeof rowClassName === 'function' ? rowClassName(record, index) : rowClassName;

              return (
                <tr
                  key={key}
                  onClick={() => onRowClick?.(record, index)}
                  className={cn(
                    'transition-colors group',
                    striped && index % 2 === 1 ? 'bg-slate-50/40' : 'bg-white',
                    isClickable
                      ? 'cursor-pointer hover:bg-emerald-50/40'
                      : 'hover:bg-slate-50/70',
                    customRowClass
                  )}
                >
                  {columns.map((col) => {
                    const stickyClasses =
                      col.sticky === 'left'
                        ? 'sticky left-0 z-10 bg-white group-hover:bg-slate-50/90 shadow-[1px_0_0_0_rgb(241,245,249)]'
                        : col.sticky === 'right'
                        ? 'sticky right-0 z-10 bg-white group-hover:bg-slate-50/90 shadow-[-1px_0_0_0_rgb(241,245,249)]'
                        : '';

                    const renderedValue = col.render
                      ? col.render(record, index)
                      : (record as any)[col.key];

                    return (
                      <td
                        key={col.key}
                        className={cn(
                          sizeBodyStyles[size],
                          stickyClasses,
                          col.align === 'center'
                            ? 'text-center'
                            : col.align === 'right'
                            ? 'text-right'
                            : 'text-left',
                          bordered ? 'border-r border-slate-100 last:border-r-0' : '',
                          col.className
                        )}
                      >
                        {renderedValue}
                      </td>
                    );
                  })}
                </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );
}

export const DataTable = Table;

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  TableProps,
  TableColumn,
  DataTableProps,
  DataTableColumn,
  TableSize,
  TableAlign,
  TableSticky,
  TableSortDirection,
} from '../../../types/ui/table.types';
