import { cn } from '../../../utils/ui/cn';

import type {
  ActionBarAlign,
  ActionBarDensity,
  ActionBarPosition,
  ActionBarProps,
  ActionBarVariant,
} from '../../../types/ui/container.types';

const positionClasses: Record<ActionBarPosition, string> = {
  top: 'border-b',
  bottom: 'border-t mt-auto',
  'sticky-top': 'sticky top-0 z-10 border-b backdrop-blur-md shadow-[0_4px_12px_rgba(0,0,0,0.03)]',
  'sticky-bottom': 'sticky bottom-0 z-10 border-t mt-auto backdrop-blur-md shadow-[0_-4px_12px_rgba(0,0,0,0.03)]',
  floating: 'sticky bottom-3 z-10 mx-3 mb-3 mt-auto rounded-xl shadow-lg ring-1 ring-black/5 backdrop-blur-md',
};

const alignClasses: Record<ActionBarAlign, string> = {
  left: 'justify-start',
  right: 'justify-end',
  between: 'justify-between',
  center: 'justify-center',
};

const densityClasses: Record<ActionBarDensity, string> = {
  tight: 'py-2 px-3.5 gap-2 text-xs',
  normal: 'py-2.5 px-5 gap-3 text-sm',
  relaxed: 'py-3.5 px-6 gap-4 text-base',
};

const variantClasses: Record<ActionBarVariant, string> = {
  default: 'bg-gradient-to-r from-slate-50/90 via-white to-slate-50/90 text-slate-700 shadow-2xs',
  floating: 'border border-slate-200/90 bg-white/95 backdrop-blur-md shadow-md ring-1 ring-slate-900/5 text-slate-700',
  subtle: 'bg-slate-50/60 text-slate-600',
  glass: 'bg-white/80 backdrop-blur-md text-slate-700 shadow-2xs',
  contrast: 'bg-slate-100/95 text-slate-800 border-slate-200',
};

export function ActionBar({
  position = 'bottom',
  align = 'between',
  density = 'normal',
  variant = 'default',
  bordered = true,
  className = '',
  children,
  leftContent,
  rightContent,
  ...props
}: ActionBarProps) {
  const hasStructuredSlots = Boolean(leftContent || rightContent);

  return (
    <div
      role="toolbar"
      aria-orientation="horizontal"
      className={cn(
        'w-full flex items-center transition-all',
        variantClasses[position === 'floating' ? 'floating' : variant],
        bordered && position !== 'floating' && 'border-slate-200/90',
        positionClasses[position],
        !hasStructuredSlots && alignClasses[align],
        densityClasses[density],
        className
      )}
      {...props}
    >
      {hasStructuredSlots ? (
        <div className="w-full flex items-center justify-between gap-3">
          <div className="flex items-center gap-2.5 min-w-0 flex-wrap">
            {leftContent}
          </div>
          <div className="flex items-center gap-2 shrink-0 flex-wrap">
            {rightContent}
            {children}
          </div>
        </div>
      ) : (
        children
      )}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { ActionBarProps } from '../../../types/ui/container.types';
