import {
  Check,
  Copy,
  Redo2,
  Search,
  Undo2,
  Wand2,
  X,
} from 'lucide-react';

import { cn } from '../../../utils/ui/cn';

import type { CodeEditorTheme } from '../../../types/ui/code-editor.types';

export function FullScreenToolbar({
  theme,
  readOnly = false,
  historyIndex,
  historyLength,
  onUndo,
  onRedo,
  language = 'json',
  isValidJson,
  onFormat,
  onMinify,
  onCopy,
  copied,
  searchTerm,
  onSearchChange,
}: FullScreenToolbarProps) {
  const isDark = theme === 'dark';

  return (
    <div
      className={cn(
        'flex flex-wrap items-center justify-between gap-2 px-4 py-1.5 border-b text-xs shrink-0 select-none transition-colors',
        isDark
          ? 'bg-slate-900/60 border-slate-800 text-slate-300'
          : 'bg-slate-50 border-slate-200 text-slate-700'
      )}
    >
      <div className="flex items-center gap-1.5">
        {/* Undo / Redo */}
        {!readOnly && (
          <>
            <button
              type="button"
              disabled={historyIndex <= 0}
              onClick={onUndo}
              className={cn(
                'p-1.5 rounded transition-colors cursor-pointer',
                isDark
                  ? 'text-slate-400 hover:text-white hover:bg-slate-800'
                  : 'text-slate-500 hover:text-slate-900 hover:bg-slate-200',
                historyIndex <= 0 ? 'opacity-30 cursor-not-allowed hover:bg-transparent' : ''
              )}
              title="Undo (Ctrl+Z)"
            >
              <Undo2 className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              disabled={historyIndex >= historyLength - 1}
              onClick={onRedo}
              className={cn(
                'p-1.5 rounded transition-colors cursor-pointer',
                isDark
                  ? 'text-slate-400 hover:text-white hover:bg-slate-800'
                  : 'text-slate-500 hover:text-slate-900 hover:bg-slate-200',
                historyIndex >= historyLength - 1 ? 'opacity-30 cursor-not-allowed hover:bg-transparent' : ''
              )}
              title="Redo (Ctrl+Y)"
            >
              <Redo2 className="w-3.5 h-3.5" />
            </button>
            <div className={cn('w-px h-4 mx-1', isDark ? 'bg-slate-800' : 'bg-slate-300')} />
          </>
        )}

        {/* Format actions */}
        {!readOnly && language === 'json' && (
          <>
            <button
              type="button"
              disabled={!isValidJson}
              onClick={() => onFormat(2)}
              className={cn(
                'flex items-center gap-1 px-2.5 py-1 rounded border transition-colors cursor-pointer',
                isDark
                  ? 'bg-slate-800 border-slate-700 text-slate-300 hover:text-white hover:bg-slate-700'
                  : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-100 hover:text-slate-900',
                !isValidJson ? 'opacity-40 cursor-not-allowed' : ''
              )}
              title="Format JSON with 2-space indentation"
            >
              <Wand2 className="w-3 h-3 text-emerald-500" />
              <span>Prettify (2sp)</span>
            </button>
            <button
              type="button"
              disabled={!isValidJson}
              onClick={onMinify}
              className={cn(
                'flex items-center gap-1 px-2.5 py-1 rounded border transition-colors cursor-pointer',
                isDark
                  ? 'bg-slate-800 border-slate-700 text-slate-300 hover:text-white hover:bg-slate-700'
                  : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-100 hover:text-slate-900',
                !isValidJson ? 'opacity-40 cursor-not-allowed' : ''
              )}
              title="Minify JSON into a single line"
            >
              <span>Minify</span>
            </button>
            <div className={cn('w-px h-4 mx-1', isDark ? 'bg-slate-800' : 'bg-slate-300')} />
          </>
        )}

        {/* Copy Button */}
        <button
          type="button"
          onClick={onCopy}
          className={cn(
            'flex items-center gap-1 px-2.5 py-1 rounded border transition-colors cursor-pointer',
            isDark
              ? 'bg-slate-800 border-slate-700 text-slate-300 hover:text-white hover:bg-slate-700'
              : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-100 hover:text-slate-900'
          )}
        >
          {copied ? <Check className="w-3 h-3 text-emerald-500" /> : <Copy className="w-3 h-3" />}
          <span>{copied ? 'Copied' : 'Copy'}</span>
        </button>
      </div>

      {/* Search Bar */}
      <div className="relative min-w-[200px]">
        <Search
          className={cn(
            'w-3.5 h-3.5 absolute left-2.5 top-2',
            isDark ? 'text-slate-400' : 'text-slate-400'
          )}
        />
        <input
          type="text"
          placeholder="Search keyword..."
          value={searchTerm}
          onChange={(e) => onSearchChange(e.target.value)}
          className={cn(
            'w-full pl-8 pr-7 py-1 text-xs border rounded-lg focus:outline-none font-mono transition-colors',
            isDark
              ? 'bg-slate-800 border-slate-700 text-white placeholder-slate-500 focus:border-emerald-500'
              : 'bg-white border-slate-300 text-slate-900 placeholder-slate-400 focus:border-emerald-500'
          )}
        />
        {searchTerm && (
          <button
            type="button"
            onClick={() => onSearchChange('')}
            className={cn(
              'absolute right-2 top-1.5 cursor-pointer',
              isDark ? 'text-slate-400 hover:text-white' : 'text-slate-400 hover:text-slate-700'
            )}
          >
            <X className="w-3.5 h-3.5" />
          </button>
        )}
      </div>
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface FullScreenToolbarProps {
  theme: CodeEditorTheme;
  readOnly?: boolean;
  historyIndex: number;
  historyLength: number;
  onUndo: () => void;
  onRedo: () => void;
  language?: string;
  isValidJson: boolean;
  onFormat: (indent?: number) => void;
  onMinify: () => void;
  onCopy: () => void;
  copied: boolean;
  searchTerm: string;
  onSearchChange: (value: string) => void;
}
