import { useCardContext } from './CardContext';

import { cn } from '../../../utils/ui/cn';

import type { CardContentProps, CardGap, CardPadding } from '../../../types/ui/card.types';

const paddingMap: Record<CardPadding, string> = {
  none: 'p-0',
  xSmall: 'px-4 py-2',
  small: 'px-5 py-3',
  medium: 'px-5 py-4',
  large: 'px-6 py-5',
};

const gapMap: Record<CardGap, string> = {
  none: '',
  xSmall: 'gap-1.5',
  small: 'gap-2.5',
  medium: 'gap-3.5',
  large: 'gap-5',
  xLarge: 'gap-7',
};

export function CardContent({
  children,
  className = '',
  padding = 'medium',
  gap = 'medium',
  ...props
}: CardContentProps) {
  const cardCtx = useCardContext();
  const isCollapsible = cardCtx?.collapsible ?? false;
  const isCollapsed = cardCtx?.isCollapsed ?? false;

  const resolvedGapKey: CardGap =
    typeof gap === 'boolean'
      ? gap
        ? 'medium'
        : 'none'
      : (gap ?? 'medium');

  const gapClass = gapMap[resolvedGapKey] || '';
  const isFlexGap = resolvedGapKey !== 'none';

  if (isCollapsible) {
    return (
      <div
        aria-hidden={isCollapsed}
        className={cn(
          'grid transition-all duration-300 ease-in-out',
          isCollapsed
            ? 'grid-rows-[0fr] opacity-0 pointer-events-none'
            : 'grid-rows-[1fr] opacity-100',
          className
        )}
        {...props}
      >
        <div className="overflow-hidden min-h-0">
          <div
            className={cn(
              paddingMap[padding],
              isFlexGap && 'flex flex-col',
              gapClass
            )}
          >
            {children}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div
      className={cn(
        paddingMap[padding],
        isFlexGap && 'flex flex-col',
        gapClass,
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { CardContentProps } from '../../../types/ui/card.types';
