import { useState } from 'react';
import {
  Check,
  ChevronDown,
  ChevronRight,
  Copy,
  Plus,
  RefreshCw,
  Search,
  Trash2,
  X,
} from 'lucide-react';

import { Badge } from '../badge';

import { cn } from '../../../utils/ui/cn';

import type {
  JsonTreeViewerProps,
  JsonValueType,
} from '../../../types/ui/code-editor.types';

function detectType(val: unknown): JsonValueType {
  if (val === null) return 'null';
  if (Array.isArray(val)) return 'array';
  if (typeof val === 'object') return 'object';
  if (typeof val === 'number') return 'number';
  if (typeof val === 'boolean') return 'boolean';
  return 'string';
}

function parseValueByType(raw: string, type: JsonValueType): unknown {
  switch (type) {
    case 'number': {
      const num = Number(raw);
      return isNaN(num) ? 0 : num;
    }
    case 'boolean':
      return raw === 'true';
    case 'null':
      return null;
    case 'object':
      try {
        const parsed = JSON.parse(raw);
        return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed) ? parsed : {};
      } catch {
        return {};
      }
    case 'array':
      try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
      } catch {
        return [];
      }
    case 'string':
    default:
      return raw;
  }
}

export function JsonTreeViewer({
  data,
  onChange,
  readOnly = false,
  theme = 'light',
  searchTerm: externalSearchTerm = '',
  className = '',
  showToolbar = true,
  showSearch = true,
  defaultExpandLevel = 2,
}: JsonTreeViewerProps) {
  const isDark = theme === 'dark';

  const [collapsedPaths, setCollapsedPaths] = useState<Set<string>>(() => {
    const initial = new Set<string>();
    const collect = (curr: unknown, path: string, level: number) => {
      if (curr && typeof curr === 'object') {
        if (level >= defaultExpandLevel && path) {
          initial.add(path);
        }
        if (Array.isArray(curr)) {
          curr.forEach((item, idx) => collect(item, path ? `${path}.${idx}` : String(idx), level + 1));
        } else {
          Object.entries(curr).forEach(([k, v]) => collect(v, path ? `${path}.${k}` : k, level + 1));
        }
      }
    };
    collect(data, '', 0);
    return initial;
  });

  const [internalSearchTerm, setInternalSearchTerm] = useState('');
  const activeSearch = externalSearchTerm || internalSearchTerm;

  // Inline value editing state
  const [editingValuePath, setEditingValuePath] = useState<string | null>(null);
  const [editValueType, setEditValueType] = useState<JsonValueType>('string');
  const [editDraftValue, setEditDraftValue] = useState<string>('');

  // Inline key renaming state
  const [editingKeyPath, setEditingKeyPath] = useState<string | null>(null);
  const [editDraftKey, setEditDraftKey] = useState<string>('');

  // Add field state
  const [addingToPath, setAddingToPath] = useState<string | null>(null);
  const [newKey, setNewKey] = useState<string>('');
  const [newValType, setNewValType] = useState<JsonValueType>('string');
  const [newVal, setNewVal] = useState<string>('');

  // Copy feedback toast
  const [copyFeedback, setCopyFeedback] = useState<string | null>(null);

  const showCopyHint = (text: string) => {
    setCopyFeedback(text);
    setTimeout(() => setCopyFeedback(null), 1500);
  };

  const isMatchingSearch = (key: string, val: unknown) => {
    if (!activeSearch.trim()) return true;
    const lower = activeSearch.toLowerCase().trim();
    if (key.toLowerCase().includes(lower)) return true;
    if (typeof val === 'string' && val.toLowerCase().includes(lower)) return true;
    if (typeof val === 'number' && String(val).includes(lower)) return true;
    if (typeof val === 'boolean' && String(val).includes(lower)) return true;
    return false;
  };

  const toggleCollapse = (path: string) => {
    setCollapsedPaths((prev) => {
      const next = new Set(prev);
      if (next.has(path)) {
        next.delete(path);
      } else {
        next.add(path);
      }
      return next;
    });
  };

  const expandAll = () => {
    setCollapsedPaths(new Set());
  };

  const collapseAll = () => {
    const allPaths = new Set<string>();
    const collect = (curr: unknown, path: string) => {
      if (curr && typeof curr === 'object') {
        if (path) allPaths.add(path);
        if (Array.isArray(curr)) {
          curr.forEach((item, idx) => collect(item, path ? `${path}.${idx}` : String(idx)));
        } else {
          Object.entries(curr).forEach(([k, v]) => collect(v, path ? `${path}.${k}` : k));
        }
      }
    };
    collect(data, '');
    setCollapsedPaths(allPaths);
  };

  const collapseToLevel = (targetLevel: number) => {
    const paths = new Set<string>();
    const collect = (curr: unknown, path: string, level: number) => {
      if (curr && typeof curr === 'object') {
        if (level >= targetLevel && path) {
          paths.add(path);
        }
        if (Array.isArray(curr)) {
          curr.forEach((item, idx) => collect(item, path ? `${path}.${idx}` : String(idx), level + 1));
        } else {
          Object.entries(curr).forEach(([k, v]) => collect(v, path ? `${path}.${k}` : k, level + 1));
        }
      }
    };
    collect(data, '', 0);
    setCollapsedPaths(paths);
  };

  const mutateData = (pathArray: (string | number)[], mutator: (target: any, lastKey: string | number) => void) => {
    if (readOnly || !onChange) return;
    try {
      const next = structuredClone(data);
      if (pathArray.length === 0) return;

      let target: any = next;
      for (let i = 0; i < pathArray.length - 1; i++) {
        target = target[pathArray[i]];
      }
      const lastKey = pathArray[pathArray.length - 1];
      mutator(target, lastKey);
      onChange(next);
    } catch (err) {
      console.error('[JsonTreeViewer] Mutation failed:', err);
    }
  };

  const handleSaveValue = (pathArray: (string | number)[]) => {
    const parsed = parseValueByType(editDraftValue, editValueType);
    mutateData(pathArray, (target, lastKey) => {
      target[lastKey] = parsed;
    });
    setEditingValuePath(null);
  };

  const handleToggleBoolean = (pathArray: (string | number)[], currentVal: boolean) => {
    mutateData(pathArray, (target, lastKey) => {
      target[lastKey] = !currentVal;
    });
  };

  const handleRenameKey = (pathArray: (string | number)[]) => {
    const trimmed = editDraftKey.trim();
    if (!trimmed) {
      setEditingKeyPath(null);
      return;
    }

    mutateData(pathArray, (target, lastKey) => {
      if (Array.isArray(target) || lastKey === trimmed) return;
      const reordered: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(target)) {
        if (k === lastKey) {
          reordered[trimmed] = v;
        } else {
          reordered[k] = v;
        }
      }
      for (const k of Object.keys(target)) {
        delete target[k];
      }
      Object.assign(target, reordered);
    });
    setEditingKeyPath(null);
  };

  const handleDelete = (pathArray: (string | number)[]) => {
    mutateData(pathArray, (target, lastKey) => {
      if (Array.isArray(target) && typeof lastKey === 'number') {
        target.splice(lastKey, 1);
      } else {
        delete target[lastKey];
      }
    });
  };

  const handleDuplicate = (pathArray: (string | number)[]) => {
    mutateData(pathArray, (target, lastKey) => {
      if (Array.isArray(target) && typeof lastKey === 'number') {
        const cloned = structuredClone(target[lastKey]);
        target.splice(lastKey + 1, 0, cloned);
      } else {
        const cloned = structuredClone(target[lastKey]);
        let copyKey = `${String(lastKey)}_copy`;
        let count = 1;
        while (copyKey in target) {
          copyKey = `${String(lastKey)}_copy_${count++}`;
        }
        target[copyKey] = cloned;
      }
    });
  };

  const handleAddField = (pathArray: (string | number)[]) => {
    mutateData(pathArray, (target, lastKey) => {
      const container = pathArray.length === 0 ? target : target[lastKey];
      const parsed = parseValueByType(newVal, newValType);
      if (Array.isArray(container)) {
        container.push(parsed);
      } else if (typeof container === 'object' && container !== null) {
        const k = newKey.trim() || `key_${Object.keys(container).length + 1}`;
        container[k] = parsed;
      }
    });
    setAddingToPath(null);
    setNewKey('');
    setNewVal('');
    setNewValType('string');
  };

  const copyToClipboard = async (text: string, label: string) => {
    try {
      await navigator.clipboard.writeText(text);
      showCopyHint(label);
    } catch {
      // Ignored
    }
  };

  const renderNode = (
    keyName: string | number,
    value: unknown,
    pathArray: (string | number)[],
    depth: number
  ) => {
    const pathStr = pathArray.join('.');
    const type = detectType(value);
    const isObject = type === 'object';
    const isArray = type === 'array';
    const isExpandable = isObject || isArray;
    const isCollapsed = collapsedPaths.has(pathStr);
    const matches = isMatchingSearch(String(keyName), value);

    const isEditingValue = editingValuePath === pathStr;
    const isEditingKey = editingKeyPath === pathStr;
    const isAddingHere = addingToPath === pathStr;

    let childCount = 0;
    if (isObject && value !== null) {
      childCount = Object.keys(value as object).length;
    } else if (isArray) {
      childCount = (value as unknown[]).length;
    }

    return (
      <div
        key={pathStr || 'root'}
        className={cn(
          'font-mono text-xs transition-colors rounded-sm',
          !matches && !isExpandable ? 'opacity-30' : '',
          depth > 0
            ? isDark
              ? 'ml-4 border-l border-slate-800/90 pl-2 my-0.5'
              : 'ml-4 border-l border-slate-200/80 pl-2 my-0.5'
            : 'my-0.5'
        )}
      >
        <div
          className={cn(
            'flex items-center gap-1.5 py-0.5 group px-1 rounded transition-colors',
            isDark ? 'hover:bg-slate-800/60' : 'hover:bg-slate-50/80'
          )}
        >
          {/* Collapse/Expand Toggle */}
          {isExpandable ? (
            <button
              type="button"
              onClick={() => toggleCollapse(pathStr)}
              className={cn(
                'w-4 h-4 flex items-center justify-center cursor-pointer shrink-0 transition-colors',
                isDark ? 'text-slate-500 hover:text-slate-200' : 'text-slate-400 hover:text-slate-700'
              )}
            >
              {isCollapsed ? <ChevronRight className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
            </button>
          ) : (
            <span className="w-4 shrink-0" />
          )}

          {/* Key / Index */}
          {keyName !== '' && (
            <>
              {isEditingKey && !readOnly ? (
                <div className="flex items-center gap-1">
                  <input
                    type="text"
                    value={editDraftKey}
                    onChange={(e) => setEditDraftKey(e.target.value)}
                    className={cn(
                      'px-1.5 py-0.5 text-xs rounded font-mono focus:outline-none',
                      isDark
                        ? 'bg-slate-800 border border-emerald-500 text-white'
                        : 'bg-white border border-emerald-500 text-slate-900'
                    )}
                    autoFocus
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') handleRenameKey(pathArray);
                      if (e.key === 'Escape') setEditingKeyPath(null);
                    }}
                  />
                  <button
                    type="button"
                    onClick={() => handleRenameKey(pathArray)}
                    className="p-0.5 text-emerald-500 hover:text-emerald-400 cursor-pointer"
                  >
                    <Check className="w-3.5 h-3.5" />
                  </button>
                  <button
                    type="button"
                    onClick={() => setEditingKeyPath(null)}
                    className="p-0.5 text-slate-400 hover:text-slate-600 cursor-pointer"
                  >
                    <X className="w-3.5 h-3.5" />
                  </button>
                </div>
              ) : (
                <span
                  className={cn(
                    'font-medium select-none cursor-pointer hover:underline',
                    typeof keyName === 'number'
                      ? isDark
                        ? 'text-amber-400'
                        : 'text-amber-700'
                      : isDark
                      ? 'text-sky-300'
                      : 'text-slate-900'
                  )}
                  title={!readOnly ? 'Double-click to edit property name' : undefined}
                  onDoubleClick={(e) => {
                    if (!readOnly && typeof keyName === 'string') {
                      e.stopPropagation();
                      setEditingKeyPath(pathStr);
                      setEditDraftKey(keyName);
                    }
                  }}
                >
                  {typeof keyName === 'number' ? `[${keyName}]` : `"${keyName}"`}:
                </span>
              )}
            </>
          )}

          {/* Value rendering */}
          {isEditingValue && !readOnly ? (
            <div className="flex items-center gap-1 flex-wrap">
              <select
                value={editValueType}
                onChange={(e) => setEditValueType(e.target.value as JsonValueType)}
                className={cn(
                  'text-[11px] rounded px-1 py-0.5 focus:outline-none cursor-pointer',
                  isDark
                    ? 'bg-slate-800 border border-slate-700 text-slate-200'
                    : 'bg-slate-100 border border-slate-300 text-slate-700'
                )}
              >
                <option value="string">string</option>
                <option value="number">number</option>
                <option value="boolean">boolean</option>
                <option value="null">null</option>
                <option value="object">object (JSON)</option>
                <option value="array">array (JSON)</option>
              </select>

              {editValueType === 'boolean' ? (
                <select
                  value={editDraftValue}
                  onChange={(e) => setEditDraftValue(e.target.value)}
                  className={cn(
                    'text-xs rounded px-1.5 py-0.5 focus:outline-none',
                    isDark
                      ? 'bg-slate-800 border border-slate-700 text-white'
                      : 'bg-white border border-slate-300 text-slate-800'
                  )}
                >
                  <option value="true">true</option>
                  <option value="false">false</option>
                </select>
              ) : editValueType === 'null' ? (
                <span className="text-xs text-slate-400 italic">null</span>
              ) : (
                <input
                  type="text"
                  value={editDraftValue}
                  onChange={(e) => setEditDraftValue(e.target.value)}
                  className={cn(
                    'px-1.5 py-0.5 text-xs rounded font-mono focus:outline-none min-w-[120px]',
                    isDark
                      ? 'bg-slate-800 border border-emerald-500 text-white'
                      : 'bg-white border border-emerald-500 text-slate-900'
                  )}
                  autoFocus
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') handleSaveValue(pathArray);
                    if (e.key === 'Escape') setEditingValuePath(null);
                  }}
                />
              )}

              <button
                type="button"
                onClick={() => handleSaveValue(pathArray)}
                className="p-0.5 text-emerald-500 hover:text-emerald-400 cursor-pointer"
              >
                <Check className="w-3.5 h-3.5" />
              </button>
              <button
                type="button"
                onClick={() => setEditingValuePath(null)}
                className="p-0.5 text-slate-400 hover:text-slate-600 cursor-pointer"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-1.5 min-w-0">
              {type === 'string' && (
                <span
                  className={cn(
                    'break-all cursor-pointer px-1 rounded transition-colors',
                    isDark
                      ? 'text-emerald-400 hover:bg-emerald-950/40'
                      : 'text-emerald-700 hover:bg-emerald-50/70'
                  )}
                  title={!readOnly ? 'Double-click to edit text' : undefined}
                  onDoubleClick={() => {
                    if (!readOnly) {
                      setEditingValuePath(pathStr);
                      setEditValueType('string');
                      setEditDraftValue(String(value));
                    }
                  }}
                >
                  "{String(value)}"
                </span>
              )}
              {type === 'number' && (
                <span
                  className={cn(
                    'font-semibold cursor-pointer px-1 rounded transition-colors',
                    isDark
                      ? 'text-cyan-400 hover:bg-cyan-950/40'
                      : 'text-blue-700 hover:bg-blue-50/70'
                  )}
                  title={!readOnly ? 'Double-click to edit number' : undefined}
                  onDoubleClick={() => {
                    if (!readOnly) {
                      setEditingValuePath(pathStr);
                      setEditValueType('number');
                      setEditDraftValue(String(value));
                    }
                  }}
                >
                  {Number(value)}
                </span>
              )}
              {type === 'boolean' && (
                <button
                  type="button"
                  disabled={readOnly}
                  onClick={() => !readOnly && handleToggleBoolean(pathArray, Boolean(value))}
                  className={cn(
                    'font-bold px-1.5 py-0.2 rounded text-[11px] transition-colors',
                    value
                      ? isDark
                        ? 'bg-emerald-950 text-emerald-400 border border-emerald-800/80'
                        : 'bg-emerald-100 text-emerald-800'
                      : isDark
                      ? 'bg-rose-950 text-rose-400 border border-rose-800/80'
                      : 'bg-rose-100 text-rose-800',
                    !readOnly ? 'cursor-pointer hover:opacity-80' : 'cursor-default'
                  )}
                  title={!readOnly ? 'Click to toggle boolean value' : undefined}
                >
                  {String(value)}
                </button>
              )}
              {type === 'null' && (
                <span
                  className={cn(
                    'italic cursor-pointer px-1 rounded',
                    isDark
                      ? 'text-slate-500 hover:bg-slate-800'
                      : 'text-slate-400 hover:bg-slate-100'
                  )}
                  title={!readOnly ? 'Double-click to edit null' : undefined}
                  onDoubleClick={() => {
                    if (!readOnly) {
                      setEditingValuePath(pathStr);
                      setEditValueType('null');
                      setEditDraftValue('');
                    }
                  }}
                >
                  null
                </span>
              )}

              {/* Collapsed object/array summary badge */}
              {isExpandable && (
                <span className={cn('text-[11px]', isDark ? 'text-slate-500' : 'text-slate-400')}>
                  {isArray ? `Array(${childCount})` : `Object{${childCount}}`}
                </span>
              )}

              {/* Type indicator badge */}
              <Badge
                variant="default"
                size="xs"
                className={cn(
                  'opacity-0 group-hover:opacity-100 transition-opacity',
                  isDark ? 'bg-slate-800 text-slate-400 border-slate-700' : ''
                )}
              >
                {type}
              </Badge>
            </div>
          )}

          {/* Row actions */}
          <div className="ml-auto opacity-0 group-hover:opacity-100 flex items-center gap-1 transition-opacity shrink-0">
            {/* Copy value */}
            <button
              type="button"
              onClick={() => copyToClipboard(JSON.stringify(value), 'Value copied!')}
              className={cn(
                'p-1 rounded cursor-pointer transition-colors',
                isDark
                  ? 'text-slate-400 hover:text-white hover:bg-slate-800'
                  : 'text-slate-400 hover:text-slate-700 hover:bg-slate-100'
              )}
              title="Copy value to clipboard"
            >
              <Copy className="w-3 h-3" />
            </button>

            {/* Add child if expandable */}
            {!readOnly && isExpandable && (
              <button
                type="button"
                onClick={() => {
                  setAddingToPath(pathStr);
                  setCollapsedPaths((prev) => {
                    const next = new Set(prev);
                    next.delete(pathStr);
                    return next;
                  });
                }}
                className={cn(
                  'p-1 rounded cursor-pointer transition-colors',
                  isDark
                    ? 'text-emerald-400 hover:text-emerald-300 hover:bg-emerald-950/50'
                    : 'text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50'
                )}
                title="Add new property"
              >
                <Plus className="w-3 h-3" />
              </button>
            )}

            {/* Duplicate node */}
            {!readOnly && depth > 0 && (
              <button
                type="button"
                onClick={() => handleDuplicate(pathArray)}
                className={cn(
                  'p-1 rounded cursor-pointer transition-colors',
                  isDark
                    ? 'text-slate-400 hover:text-white hover:bg-slate-800'
                    : 'text-slate-400 hover:text-slate-700 hover:bg-slate-100'
                )}
                title="Duplicate this item"
              >
                <RefreshCw className="w-3 h-3" />
              </button>
            )}

            {/* Delete node */}
            {!readOnly && depth > 0 && (
              <button
                type="button"
                onClick={() => handleDelete(pathArray)}
                className={cn(
                  'p-1 rounded cursor-pointer transition-colors',
                  isDark
                    ? 'text-rose-400 hover:text-rose-300 hover:bg-rose-950/50'
                    : 'text-rose-500 hover:text-rose-700 hover:bg-rose-50'
                )}
                title="Delete this property"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            )}
          </div>
        </div>

        {/* Inline Add Field Form */}
        {isAddingHere && !readOnly && (
          <div
            className={cn(
              'ml-6 my-1 p-2 rounded-lg flex flex-wrap items-center gap-2 animate-in fade-in duration-100 border',
              isDark
                ? 'bg-slate-900 border-slate-700'
                : 'bg-emerald-50/70 border-emerald-200'
            )}
          >
            {!isArray && (
              <input
                type="text"
                placeholder="Property name..."
                value={newKey}
                onChange={(e) => setNewKey(e.target.value)}
                className={cn(
                  'px-2 py-1 text-xs rounded font-mono focus:outline-none w-32',
                  isDark
                    ? 'bg-slate-800 border border-slate-700 text-white focus:border-emerald-500'
                    : 'bg-white border border-slate-300 text-slate-800 focus:border-emerald-500'
                )}
                autoFocus
              />
            )}
            <select
              value={newValType}
              onChange={(e) => setNewValType(e.target.value as JsonValueType)}
              className={cn(
                'text-xs rounded px-2 py-1 focus:outline-none cursor-pointer',
                isDark
                  ? 'bg-slate-800 border border-slate-700 text-slate-200'
                  : 'bg-white border border-slate-300 text-slate-800'
              )}
            >
              <option value="string">string</option>
              <option value="number">number</option>
              <option value="boolean">boolean</option>
              <option value="null">null</option>
              <option value="object">object</option>
              <option value="array">array</option>
            </select>

            {newValType === 'boolean' ? (
              <select
                value={newVal}
                onChange={(e) => setNewVal(e.target.value)}
                className={cn(
                  'text-xs rounded px-2 py-1 focus:outline-none',
                  isDark
                    ? 'bg-slate-800 border border-slate-700 text-white'
                    : 'bg-white border border-slate-300 text-slate-800'
                )}
              >
                <option value="true">true</option>
                <option value="false">false</option>
              </select>
            ) : newValType === 'null' ? (
              <span className="text-xs text-slate-400 italic">null</span>
            ) : (
              <input
                type="text"
                placeholder="Value..."
                value={newVal}
                onChange={(e) => setNewVal(e.target.value)}
                className={cn(
                  'px-2 py-1 text-xs rounded font-mono focus:outline-none flex-1 min-w-[120px]',
                  isDark
                    ? 'bg-slate-800 border border-slate-700 text-white focus:border-emerald-500'
                    : 'bg-white border border-slate-300 text-slate-800 focus:border-emerald-500'
                )}
              />
            )}

            <button
              type="button"
              onClick={() => handleAddField(pathArray)}
              className="px-2.5 py-1 text-xs bg-emerald-600 text-white font-medium rounded hover:bg-emerald-500 cursor-pointer shadow-2xs"
            >
              Add
            </button>
            <button
              type="button"
              onClick={() => setAddingToPath(null)}
              className={cn(
                'px-2 py-1 text-xs cursor-pointer',
                isDark ? 'text-slate-400 hover:text-white' : 'text-slate-600 hover:text-slate-900'
              )}
            >
              Cancel
            </button>
          </div>
        )}

        {/* Children rendering if expanded */}
        {isExpandable && !isCollapsed && (
          <div>
            {isArray &&
              (value as unknown[]).map((item, idx) =>
                renderNode(idx, item, [...pathArray, idx], depth + 1)
              )}
            {isObject &&
              value !== null &&
              Object.entries(value as Record<string, unknown>).map(([k, v]) =>
                renderNode(k, v, [...pathArray, k], depth + 1)
              )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div
      className={cn(
        'flex flex-col w-full rounded-xl select-text relative transition-colors',
        isDark ? 'bg-slate-950 text-slate-100' : 'bg-white text-slate-800',
        className
      )}
    >
      {/* Toast Feedback */}
      {copyFeedback && (
        <div className="absolute top-2 right-2 z-20 bg-slate-900 text-white text-xs px-3 py-1 rounded-lg shadow-md animate-in fade-in duration-100 flex items-center gap-1.5 border border-slate-700">
          <Check className="w-3.5 h-3.5 text-emerald-400" />
          <span>{copyFeedback}</span>
        </div>
      )}

      {/* Toolbar */}
      {showToolbar && (
        <div
          className={cn(
            'flex flex-wrap items-center justify-between gap-2 p-2 border-b text-xs select-none',
            isDark
              ? 'bg-slate-900/90 border-slate-800'
              : 'bg-slate-50/80 border-slate-200'
          )}
        >
          <div className="flex items-center gap-1.5 flex-wrap">
            <button
              type="button"
              onClick={expandAll}
              className={cn(
                'px-2 py-1 rounded border text-xs font-medium cursor-pointer shadow-2xs transition-colors',
                isDark
                  ? 'bg-slate-800 border-slate-700 text-slate-200 hover:bg-slate-700 hover:text-white'
                  : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-100'
              )}
            >
              Expand All
            </button>
            <button
              type="button"
              onClick={collapseAll}
              className={cn(
                'px-2 py-1 rounded border text-xs font-medium cursor-pointer shadow-2xs transition-colors',
                isDark
                  ? 'bg-slate-800 border-slate-700 text-slate-200 hover:bg-slate-700 hover:text-white'
                  : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-100'
              )}
            >
              Collapse All
            </button>
            <button
              type="button"
              onClick={() => collapseToLevel(1)}
              className={cn(
                'px-2 py-1 rounded border text-xs font-medium cursor-pointer shadow-2xs transition-colors',
                isDark
                  ? 'bg-slate-800 border-slate-700 text-slate-200 hover:bg-slate-700 hover:text-white'
                  : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-100'
              )}
            >
              Level 1
            </button>
            <button
              type="button"
              onClick={() => collapseToLevel(2)}
              className={cn(
                'px-2 py-1 rounded border text-xs font-medium cursor-pointer shadow-2xs transition-colors',
                isDark
                  ? 'bg-slate-800 border-slate-700 text-slate-200 hover:bg-slate-700 hover:text-white'
                  : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-100'
              )}
            >
              Level 2
            </button>
          </div>

          {showSearch && (
            <div className="relative min-w-[160px]">
              <Search className="w-3.5 h-3.5 absolute left-2 top-2 text-slate-400" />
              <input
                type="text"
                placeholder="Search properties..."
                value={internalSearchTerm}
                onChange={(e) => setInternalSearchTerm(e.target.value)}
                className={cn(
                  'w-full pl-7 pr-6 py-1 text-xs border rounded-lg focus:outline-none font-mono transition-colors',
                  isDark
                    ? 'bg-slate-800 border-slate-700 text-white placeholder-slate-500 focus:border-emerald-500'
                    : 'bg-white border-slate-300 text-slate-900 placeholder-slate-400 focus:border-emerald-500'
                )}
              />
              {internalSearchTerm && (
                <button
                  type="button"
                  onClick={() => setInternalSearchTerm('')}
                  className="absolute right-1.5 top-1.5 text-slate-400 hover:text-slate-200 cursor-pointer"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              )}
            </div>
          )}
        </div>
      )}

      {/* Main Tree Container */}
      <div className="p-3 overflow-auto max-h-[600px]">
        {data === null || data === undefined ? (
          <div className={cn('text-xs italic p-4 text-center', isDark ? 'text-slate-500' : 'text-slate-400')}>
            Empty data / null
          </div>
        ) : (
          renderNode('', data, [], 0)
        )}
      </div>
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  CodeEditorTheme,
  JsonTreeEditorProps,
  JsonTreeViewerProps,
  JsonValueType,
} from '../../../types/ui/code-editor.types';
