import { useMemo, useState } from 'react';

import { CardProvider } from './CardContext';
import { CardHeader } from './CardHeader';
import { CardTitle } from './CardTitle';
import { CardDescription } from './CardDescription';
import { CardContent } from './CardContent';
import { CardFooter } from './CardFooter';
import { FeatureBanner } from './FeatureBanner';
import { ActionBar } from '../container/ActionBar';

import { cn } from '../../../utils/ui/cn';

import type {
  CardGap,
  CardPadding,
  CardProps,
  CardVariant,
} from '../../../types/ui/card.types';

const paddingMap: Record<CardPadding, string> = {
  none: 'p-0',
  xSmall: 'p-2',
  small: 'p-4',
  medium: 'p-5',
  large: 'p-6',
};

const gapMap: Record<CardGap, string> = {
  none: '',
  xSmall: 'gap-1.5',
  small: 'gap-2.5',
  medium: 'gap-3.5',
  large: 'gap-5',
  xLarge: 'gap-7',
};

const variantClasses: Record<CardVariant, string> = {
  default: 'bg-white border border-slate-200/90 shadow-xs text-slate-900',
  light: 'bg-white border border-slate-200/80 shadow-xs text-slate-900',
  bordered: 'bg-white border border-slate-200 shadow-none text-slate-900',
  ghost: 'bg-transparent border-transparent shadow-none text-slate-900',
  flat: 'bg-slate-50/90 border border-slate-200/80 shadow-none text-slate-900',
  elevated: 'bg-white border border-slate-200/70 shadow-md text-slate-900',
};

export function Card({
  children,
  className = '',
  padding = 'none',
  gap = 'medium',
  variant = 'default',
  hoverable = false,
  collapsible = false,
  defaultCollapsed = false,
  isCollapsed: controlledCollapsed,
  onToggleCollapse,
  title,
  description,
  icon,
  iconBgColor,
  badge,
  actionSlot,
  actions,
  headerClassName = '',
  bodyClassName = '',
  ...props
}: CardProps) {
  const [internalCollapsed, setInternalCollapsed] = useState(defaultCollapsed);
  const isControlled = controlledCollapsed !== undefined;
  const isCollapsed = isControlled ? controlledCollapsed : internalCollapsed;

  const handleToggle = () => {
    const next = !isCollapsed;
    if (!isControlled) {
      setInternalCollapsed(next);
    }
    onToggleCollapse?.(next);
  };

  const contextValue = useMemo(
    () => ({
      collapsible,
      isCollapsed,
      toggleCollapse: handleToggle,
    }),
    [collapsible, isCollapsed]
  );

  const hasDirectHeader = Boolean(title || description || icon || badge || actionSlot || actions);

  const resolvedGapKey: CardGap =
    typeof gap === 'boolean'
      ? gap
        ? 'medium'
        : 'none'
      : (gap ?? 'none');

  const gapClass = !hasDirectHeader && resolvedGapKey !== 'none' ? `flex flex-col ${gapMap[resolvedGapKey]}` : '';

  return (
    <CardProvider value={contextValue}>
      <div
        className={cn(
          'rounded-2xl transition-all overflow-hidden',
          variantClasses[variant],
          hoverable && 'hover:shadow-md hover:border-slate-300',
          !hasDirectHeader && paddingMap[padding],
          gapClass,
          className
        )}
        {...props}
      >
        {hasDirectHeader ? (
          <>
            <CardHeader
              title={title}
              description={description}
              icon={icon}
              iconBgColor={iconBgColor}
              badge={badge}
              actionSlot={actionSlot}
              actions={actions}
              className={headerClassName}
            />
            <CardContent
              padding={padding === 'none' ? 'medium' : padding}
              gap={gap}
              className={bodyClassName}
            >
              {children}
            </CardContent>
          </>
        ) : (
          children
        )}
      </div>
    </CardProvider>
  );
}

// Compound sub-components
Card.Header = CardHeader;
Card.Title = CardTitle;
Card.Description = CardDescription;
Card.Content = CardContent;
Card.Footer = CardFooter;
Card.FeatureBanner = FeatureBanner;
Card.ActionBar = ActionBar;

// ============================================================================
// SUB-COMPONENTS
// ============================================================================
export { CardHeader } from './CardHeader';
export { CardTitle } from './CardTitle';
export { CardDescription } from './CardDescription';
export { CardContent } from './CardContent';
export { CardFooter } from './CardFooter';
export { FeatureBanner } from './FeatureBanner';
export { useCardContext } from './CardContext';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  CardProps,
  CardHeaderProps,
  CardTitleProps,
  CardContentProps,
  CardFooterProps,
  FeatureBannerProps,
  CardPadding,
  CardGap,
  CardVariant,
} from '../../../types/ui/card.types';
export type { CardContextValue } from './CardContext';
