import { forwardRef } from 'react';

import { FieldWrapper } from '../field-wrapper';
import { Radio } from './Radio';

import { cn } from '../../../../utils/ui/cn';

import type { RadioGroupProps } from '../../../../types/ui/field/radio.types';

export const RadioGroup = forwardRef<HTMLDivElement, RadioGroupProps>(
  (
    {
      options,
      value,
      onChange,
      name,
      label,
      error,
      helperText,
      hint,
      required,
      optional,
      orientation = 'vertical',
      variant = 'default',
      size = 'md',
      disabled = false,
      className,
      ...props
    },
    ref
  ) => {
    const isHorizontal = orientation === 'horizontal';

    const groupNode = (
      <div
        ref={ref}
        role="radiogroup"
        className={cn(
          isHorizontal ? 'flex flex-wrap items-center gap-4' : 'flex flex-col space-y-2.5',
          className
        )}
        {...props}
      >
        {options.map((option) => (
          <Radio
            key={option.value}
            name={name}
            value={option.value}
            checked={value === option.value}
            onChange={() => onChange?.(option.value)}
            label={option.label}
            description={option.description}
            disabled={disabled || option.disabled}
            size={size}
            variant={variant}
          />
        ))}
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={size}
        >
          {groupNode}
        </FieldWrapper>
      );
    }

    return groupNode;
  }
);

RadioGroup.displayName = 'RadioGroup';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { RadioGroupProps, RadioOption } from '../../../../types/ui/field/radio.types';
